check "static pod node-agent runs on $MAIN_W1 (manifest in the kubelet's staticPodPath)" bash -c "node_exec $MAIN_W1 'ls /etc/kubernetes/manifests/' | grep -q . && pod_ready main node-agent-$MAIN_W1 default && [ \"\$(kubectl --context main get pod node-agent-$MAIN_W1 -o jsonpath='{.metadata.ownerReferences[0].kind}')\" = Node ]"
check "node-agent is Guaranteed QoS with 50m CPU / 32Mi memory" bash -c "[ \"\$(kubectl --context main get pod node-agent-$MAIN_W1 -o jsonpath='{.status.qosClass} {.spec.containers[0].resources.limits.cpu} {.spec.containers[0].resources.limits.memory}')\" = 'Guaranteed 50m 32Mi' ]"
check "only $MAIN_W2 carries disk=ssd" bash -c "[ \"\$(kubectl --context main get nodes -l disk=ssd -o name)\" = node/$MAIN_W2 ]"
check "edge-cache requires disk=ssd via node affinity and all 3 pods run on $MAIN_W2" bash -c "[ \"\$(kubectl --context main -n edge-cache get deploy edge-cache -o jsonpath='{.spec.template.spec.affinity.nodeAffinity.requiredDuringSchedulingIgnoredDuringExecution.nodeSelectorTerms[0].matchExpressions[0].key}')\" = disk ] && deploy_ready main edge-cache edge-cache 3 && [ \"\$(kubectl --context main -n edge-cache get pods -l app=edge-cache --field-selector=status.phase=Running -o jsonpath='{range .items[*]}{.spec.nodeName}{\"\\n\"}{end}' | sort -u)\" = $MAIN_W2 ]"
